// ---- 工具：标签流体 ----
// 走 Java 侧 LensCircuitFluidTags.tagFluid（纯 Java，无 JSON、无 Rhino 编组）。
// 为什么不用 KubeJS 字符串：FluidStackJS.of(String) 只认 'id amount'，不认 '#tag'。
// 为什么不用 JsonParser：第一次冒烟实测在 Rhino 下当场抛 JsonSyntaxException（见文件头 v2 说明）。
var SHANHAI_FLUID_TAGS = null
var SHANHAI_FLUID_TAGS_MISSING = false
var SHANHAI_TAG_FALLBACK = 0
var SHANHAI_TAG_FALLBACK_LOG = ''
// 标签 → 具体流体 的退路：全部取自 dgy 自己的写法（dgy.js 里同一批配方写的就是这些具体流体）
var SHANHAI_TAG_FALLBACK_MAP = {
    'forge:photoresist': 'gtceu:photoresist',
    'forge:euv_photoresist': 'gtceu:euv_photoresist',
    'forge:gamma_rays_photoresist': 'gtceu:gamma_rays_photoresist',
    'forge:cosmic': 'gtceu:cosmic',
    'forge:spacetime': 'gtceu:spacetime',
    'forge:primordialmatter': 'gtceu:primordialmatter'
}
function SHANHAI_FLUID(x) {
    var amount = x[0]
    var id = x[1]
    if (id.charAt(0) !== '#') return id + ' ' + amount
    var tag = id.substring(1)
    if (!SHANHAI_FLUID_TAGS_MISSING) {
        try {
            if (SHANHAI_FLUID_TAGS === null) {
                SHANHAI_FLUID_TAGS = Java.loadClass('com.shanhai.common.recipe.LensCircuitFluidTags')
            }
            return SHANHAI_FLUID_TAGS.tagFluid(tag, amount)
        } catch (e) {
            SHANHAI_FLUID_TAGS_MISSING = true
            console.error('[SHANHAI-LENS2C] 🔴 标签流体构造失败，退到具体流体：' + tag + ' 原因: ' + e)
        }
    }
    // 退路：响亮告警 + 计数（绝不静默）
    var concrete = SHANHAI_TAG_FALLBACK_MAP[tag]
    if (!concrete) {
        throw new Error('[SHANHAI-LENS2C] 标签流体 ' + tag + ' 既建不出来、也没有登记退路')
    }
    SHANHAI_TAG_FALLBACK = SHANHAI_TAG_FALLBACK + 1
    if (SHANHAI_TAG_FALLBACK_LOG.length < 600) SHANHAI_TAG_FALLBACK_LOG = SHANHAI_TAG_FALLBACK_LOG + ' ' + tag + '->' + concrete
    return concrete + ' ' + amount
}

// ---- 双实现对照 + 通用建配方 ----
var SHANHAI_L2C_MAP = null
var SHANHAI_L2C_MISSING = false
function SHANHAI_L2C_CHECK(r) {
    if (SHANHAI_L2C_MISSING) return
    if (SHANHAI_L2C_MAP === null) {
        try { SHANHAI_L2C_MAP = Java.loadClass('com.shanhai.common.recipe.PrimordialLensCircuitMap') }
        catch (e) {
            SHANHAI_L2C_MISSING = true
            console.warn('[SHANHAI-LENS2C] ⚠️ 找不到 Java 侧纯表核 PrimordialLensCircuitMap ⇒ 跳过双实现对照。'
                + '（通常是当前装的还是旧 jar）: ' + e)
            return
        }
    }
    // ⚠️ 刻意【既不少传数组、也不传 null】：
    //    · 不传数组 —— Rhino 调 Java 可变参数要隐式转 NativeArray→String[]，那条路没实测过；
    //    · 不传 null —— 少一个 Rhino 编组的不确定点，改传空串（Java 侧同样当"没有透镜"）。
    //    🔴 且 Java 侧 PrimordialLensCircuitMap 现在【只剩一个】circuitFor 重载 ——
    //       原先 (String,String) 与 (String,String...) 并存时，Rhino 判不出该调哪个，
    //       抛 InternalError: The choice of Java method ... (string,string) is ambiguous
    //       ⇒ 311 条配方一条都没建出来（2026-09-30 实测，见 handoff 报告 §5.5）。
    var expect = SHANHAI_L2C_MAP.circuitFor(r.sk, r.lens.length ? r.lens : '')
    if (1 * expect !== 1 * r.c) {
        throw new Error('[SHANHAI-LENS2C] 🔴 双实现不一致：' + r.id + ' 本文件 c=' + r.c
            + ' 而 Java 纯表核给 ' + expect + '（srcKey=' + r.sk + ' lens=' + r.lens + '）')
    }
}

function SHANHAI_BUILD_LENS2CIRCUIT(gtr, typeId, table, tag) {
    var st = { ok: 0, bad: 0, errs: '' }
    for (var i = 0; i < table.length; i++) {
        var r = table[i]
        try {
            SHANHAI_L2C_CHECK(r)
            var b = gtr[typeId](r.id)
            var k
            for (k = 0; k < r.nc.length; k++) b = b.notConsumable(r.nc[k])
            if (r.c > 0) b = b.circuit(r.c)
            for (k = 0; k < r.in.length; k++) b = b.itemInputs(r.in[k])
            for (k = 0; k < r.fl.length; k++) b = b.inputFluids(SHANHAI_FLUID(r.fl[k]))
            for (k = 0; k < r.out.length; k++) b = b.itemOutputs(r.out[k])
            for (k = 0; k < r.fo.length; k++) b = b.outputFluids(SHANHAI_FLUID(r.fo[k]))
            if (r.data) { for (k = 0; k < r.data.length; k++) b = b.addData(r.data[k][0], r.data[k][1]) }
            if (r.clean) b = b.cleanroom(CleanroomType.CLEANROOM)
            b.duration(r.dur).EUt(r.eu)
            st.ok = st.ok + 1
        } catch (e) {
            st.bad = st.bad + 1
            if (st.errs.length < 1500) st.errs = st.errs + '|' + r.id + ' <= ' + e + ' '
        }
    }
    console.info('[SHANHAI-NEWTYPE] ' + tag + ' type=' + typeId
        + ' ok=' + st.ok + ' failed=' + st.bad + ' declared=' + table.length
        + ' lens->circuit 映射表见 handoff\\outbound\\原初激光蚀刻与蜂群铸造.md §3')
    if (st.bad > 0) console.error('[SHANHAI-NEWTYPE] ' + tag + ' 失败明细：' + st.errs)
    else if (SHANHAI_TAG_FALLBACK > 0) console.warn('[SHANHAI-NEWTYPE] ' + tag
        + ' 有 ' + SHANHAI_TAG_FALLBACK + ' 处走了"标签→具体流体"退路：' + SHANHAI_TAG_FALLBACK_LOG)
    return st
}

